import React, { useRef, useState, useEffect } from 'react';
import { ThreeSky } from './components/clouds/ThreeSky';
import { SandFog } from './components/special-effects/SandFog';
import { Horizon } from './components/special-effects/Horizon';
import { Floor } from './components/special-effects/Floor';
import { UpperDust } from './components/special-effects/UpperDust';
import { Navigation } from './components/ui/Navigation';

const App: React.FC = () => {
    const viewerRef = useRef<HTMLDivElement>(null);
    const scrollRef = useRef<number>(0); 
    const [scrollX, setScrollX] = useState(0); 
    const [activeIndex, setActiveIndex] = useState(1); 

    useEffect(() => {
        if (viewerRef.current) {
            const startX = window.innerWidth;
            viewerRef.current.scrollTo({ left: startX, behavior: 'auto' });
            scrollRef.current = startX;
            setScrollX(startX);
        }

        const handleScroll = () => {
            if (viewerRef.current) {
                const currentX = viewerRef.current.scrollLeft;
                scrollRef.current = currentX; 

                requestAnimationFrame(() => {
                    setScrollX(currentX);
                    setActiveIndex(Math.round(currentX / window.innerWidth));
                });
            }
        };

        const currentViewer = viewerRef.current;
        if (currentViewer) {
            currentViewer.addEventListener('scroll', handleScroll, { passive: true });
        }

        return () => {
            if (currentViewer) {
                currentViewer.removeEventListener('scroll', handleScroll);
            }
        };
    }, []);

    const handleDotClick = (index: number) => {
        if (viewerRef.current) {
            const target = index * window.innerWidth;
            viewerRef.current.scrollTo({ left: target, behavior: 'smooth' });
        }
    };

    return (
        <div className="bg-black overflow-hidden relative h-screen w-screen select-none font-sans text-white">

            {/* Capa de Fondo Fija: Cielo (Parallax gestionado por ThreeSky) */}
            <div className="absolute inset-0 z-0 pointer-events-none">
                <ThreeSky scrollRef={scrollRef} />
            </div>

            {/* Efecto de Polvo Superior (UpperDust) 
                Z-Index intermedio: Encima del cielo, detrás de las montañas.
            */}
            <UpperDust />

            {/* 
                Contenedor de Scroll Principal
                Contiene el Horizonte (montañas) y el Floor (piso) como capas de 300vw.
            */}
            <div 
                ref={viewerRef}
                id="viewer" 
                className="relative z-10 w-full h-full overflow-x-auto scroll-smooth snap-x snap-mandatory flex flex-row [&::-webkit-scrollbar]:hidden [-ms-overflow-style:'none'] [scrollbar-width:'none']"
            >
                {/* Capas Panorámicas (300vw cada una) */}
                <Horizon />
                <Floor />

                {/* 
                   ANCLAS DE NAVEGACIÓN (Panes)
                   Ahora son invisibles y solo sirven para que el scroll se detenga 
                   exactamente en 0vw, 100vw y 200vw.
                */}
                <div className="min-w-[100vw] h-full flex-shrink-0 snap-start pointer-events-none" />
                <div className="min-w-[100vw] h-full flex-shrink-0 snap-start pointer-events-none" />
                <div className="min-w-[100vw] h-full flex-shrink-0 snap-start pointer-events-none" />
            </div>

            {/* Efectos de primer plano: Niebla de arena con parallax inverso sutil */}
            <SandFog parallaxX={scrollX * 0.4} />

            {/* UI de Navegación */}
            <Navigation totalPanes={3} activeIndex={activeIndex} onDotClick={handleDotClick} />

        </div>
    );
};

export default App;

