import React, { useEffect, useRef } from 'react';
import * as THREE from 'three';

const CLOUD_URLS = [
    'https://i.imgur.com/JTrVDQ3.png', 'https://i.imgur.com/58lHfHw.png',
    'https://i.imgur.com/X8FIpPe.png', 'https://i.imgur.com/hcdTnXq.png',
    'https://i.imgur.com/C08w8E1.png', 'https://i.imgur.com/Nypf6gX.png',
    'https://i.imgur.com/jd76dmd.png'
];

interface ThreeSkyProps {
    scrollRef: React.MutableRefObject<number>;
}

export const ThreeSky: React.FC<ThreeSkyProps> = ({ scrollRef }) => {
    const containerRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        if (!containerRef.current) return;

        const w = containerRef.current.clientWidth;
        const h = containerRef.current.clientHeight;
        const aspect = w / h;

        // Configuración básica de Three.js
        const scene = new THREE.Scene();
        const frustumSize = 1000;
        const camera = new THREE.OrthographicCamera(
            frustumSize * aspect / -2,
            frustumSize * aspect / 2,
            frustumSize / 2,
            frustumSize / -2,
            1,
            2000
        );
        camera.position.z = 1000;

        const renderer = new THREE.WebGLRenderer({ alpha: true, antialias: false, powerPreference: "high-performance" });
        renderer.setSize(w, h);
        renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));

        renderer.domElement.style.position = 'absolute';
        renderer.domElement.style.top = '0';
        renderer.domElement.style.left = '0';
        renderer.domElement.style.zIndex = '1';

        containerRef.current.appendChild(renderer.domElement);

        const clouds: THREE.Mesh[] = [];
        const loader = new THREE.TextureLoader();

        // 1. TAMAÑO MUCHO MÁS PEQUEÑO: 
        // Geometría base reducida a 60x40 (antes 350x250)
        const cloudGeo = new THREE.PlaneGeometry(60, 40);
        const clock = new THREE.Clock();

        const getSceneWidth = () => 1000 * (containerRef.current?.clientWidth || 1000) / (containerRef.current?.clientHeight || 1000);

        // Función para reiniciar una nube en una posición aleatoria
        const respawnCloud = (sprite: THREE.Mesh) => {
            const sceneW = getSceneWidth();
            // Área de aparición: Ancho visible + un margen pequeño
            const rangeX = sceneW * 1.2; 

            // Posición totalmente aleatoria cada vez
            sprite.position.x = (Math.random() * rangeX) - (rangeX / 2);
            // Altura aleatoria en la mitad superior
            sprite.position.y = (Math.random() * 250) + 150; 
            sprite.position.z = Math.random() * 200 - 100; // Profundidad variada

            const flip = Math.random() > 0.5 ? -1 : 1;
            // Escala aleatoria pequeña (0.8 a 1.5 veces el tamaño base de 60px)
            const scale = 0.8 + Math.random() * 0.7; 
            sprite.scale.set(scale * flip, scale, 1);

            // Estado inicial del ciclo de vida
            // Phase: 0=FadeIn, 1=Hold, 2=FadeOut, 3=Dead/Waiting
            sprite.userData.phase = 0; 
            sprite.userData.timer = 0;
            // Opacidad empieza en 0
            // @ts-ignore
            sprite.material.opacity = 0;

            // CONFIGURACIÓN DE TIEMPOS (Total aprox 2.5s - 3.0s)
            sprite.userData.fadeInTime = 0.8 + Math.random() * 0.4; // ~1s aparecer
            sprite.userData.holdTime = 0.5 + Math.random() * 0.5;   // ~0.7s mantenerse
            sprite.userData.fadeOutTime = 0.8 + Math.random() * 0.4; // ~1s desaparecer

            // Retraso inicial aleatorio para que no aparezcan todas juntas al cargar
            sprite.userData.startDelay = Math.random() * 2.0;

            // Parallax factor suave
            sprite.userData.parallax = 0.05 + Math.random() * 0.1;
            sprite.userData.baseX = sprite.position.x;
        };

        const CLOUD_COUNT = 8; // Cantidad controlada

        for (let i = 0; i < CLOUD_COUNT; i++) {
            const url = CLOUD_URLS[i % CLOUD_URLS.length];
            loader.load(url, (texture) => {
                const material = new THREE.MeshBasicMaterial({
                    map: texture,
                    transparent: true,
                    depthWrite: false,
                    opacity: 0 // Empiezan invisibles
                });
                const sprite = new THREE.Mesh(cloudGeo, material);

                // Inicializar datos
                sprite.userData = { phase: 3, timer: 0 }; 
                respawnCloud(sprite);

                scene.add(sprite);
                clouds.push(sprite);
            });
        }

        let animationId: number;

        const animate = () => {
            animationId = requestAnimationFrame(animate);
            if (!containerRef.current) return;

            const delta = clock.getDelta();

            const currentW = containerRef.current.clientWidth;
            const currentAspect = currentW / containerRef.current.clientHeight;
            const sceneVisibleWidth = 1000 * currentAspect; 
            const pixelToUnitRatio = sceneVisibleWidth / currentW;

            clouds.forEach(cloud => {
                const data = cloud.userData;
                // @ts-ignore
                const mat = cloud.material;

                // Máquina de estados del ciclo de vida
                if (data.startDelay > 0) {
                    data.startDelay -= delta;
                    return;
                }

                if (data.phase === 0) { // FADE IN
                    data.timer += delta;
                    const progress = Math.min(data.timer / data.fadeInTime, 1);
                    // Sube de 0 a 0.7
                    mat.opacity = progress * 0.7;
                    if (progress >= 1) {
                        data.phase = 1;
                        data.timer = 0;
                    }
                } else if (data.phase === 1) { // HOLD
                    data.timer += delta;
                    if (data.timer >= data.holdTime) {
                        data.phase = 2;
                        data.timer = 0;
                    }
                } else if (data.phase === 2) { // FADE OUT
                    data.timer += delta;
                    const progress = Math.min(data.timer / data.fadeOutTime, 1);
                    // Baja de 0.7 a 0
                    mat.opacity = 0.7 - (progress * 0.7);
                    if (progress >= 1) {
                        data.phase = 3; // Muerte
                    }
                } else if (data.phase === 3) { // RESPAWN
                    respawnCloud(cloud);
                }

                // Efecto Parallax muy suave (Solo posición, sin envoltura necesaria por el ciclo corto)
                const parallaxEffect = (scrollRef.current - window.innerWidth) * pixelToUnitRatio * data.parallax;
                cloud.position.x = data.baseX - parallaxEffect;
            });

            renderer.render(scene, camera);
        };

        animate();

        const handleResize = () => {
            if (!containerRef.current) return;
            const newW = containerRef.current.clientWidth;
            const newH = containerRef.current.clientHeight;
            const newAspect = newW / newH;
            camera.left = -frustumSize * newAspect / 2;
            camera.right = frustumSize * newAspect / 2;
            camera.updateProjectionMatrix();
            renderer.setSize(newW, newH);
        };

        window.addEventListener('resize', handleResize);
        return () => {
            window.removeEventListener('resize', handleResize);
            cancelAnimationFrame(animationId);
            if (containerRef.current) containerRef.current.removeChild(renderer.domElement);
            renderer.dispose();
        };
    }, []);

    return (
        <div 
            id="cielo-container" 
            ref={containerRef}
            className="w-full h-full relative overflow-hidden" 
            style={{ 
                background: 'linear-gradient(180deg, #1E90FF 0%, #87CEFA 100%)', 
                zIndex: 0 
            }}
        >
            <div 
                className="absolute inset-0 w-full h-full pointer-events-none"
                style={{
                    background: 'linear-gradient(to bottom, transparent 0%, rgba(200, 225, 255, 0) 50%, rgba(255, 255, 255, 0.5) 80%, #FFFFFF 100%)',
                    zIndex: 0
                }}
            />
        </div>
    );
};

